	r.HandleFunc(options.BaseURL+"/api/persons", wrapper.CreatePerson).Methods(http.MethodPost)

	r.HandleFunc(options.BaseURL+"/api/persons/{id}", wrapper.DeletePerson).Methods(http.MethodDelete)

